def merge_sort(values):
    """使用归并排序返回升序新列表，不修改传入的数据。"""
    items = list(values)

    def sort(items):
        if len(items) <= 1:
            return items

        middle = len(items) // 2
        left = sort(items[:middle])
        right = sort(items[middle:])
        merged = []
        i = j = 0

        while i < len(left) and j < len(right):
            # 相等时优先保留左侧元素，保证排序稳定。
            if right[j] < left[i]:
                merged.append(right[j])
                j += 1
            else:
                merged.append(left[i])
                i += 1

        merged.extend(left[i:])
        merged.extend(right[j:])
        return merged

    return sort(items)


if __name__ == "__main__":
    numbers = [64, 34, 25, 12, 22, 11, 90]
    print("原始数据：", numbers)
    print("排序结果：", merge_sort(numbers))

